/* @lc app=leetcode id=2454 lang=kotlin */ class Solution { fun secondGreaterElement(nums: IntArray): IntArray = IntArray(nums.size) { -1 }.also { ans -> java.util.ArrayDeque<Int>().let { s1 -> java.util.ArrayDeque<Int>().let { s2 -> nums.indices.forEach { i -> generateSequence { s2.peekFirst()?.takeIf { nums[it] < nums[i] } }.forEach { _ -> s2.pollFirst().let { ans[it] = nums[i] } }.let { generateSequence { s1.peekFirst()?.takeIf { nums[it] < nums[i] } }.map { s1.pollFirst() }.toList().reversed().forEach { s2.addFirst(it) } }.let { s1.addFirst(i) } } } } } }